import json,struct
fmap=json.load(open("_fmap.json"))
fmap={int(k):v for k,v in fmap.items()}
raw=bytes.fromhex("")
base=0x7100247390
for i in range(0,len(raw),8):
    v=struct.unpack_from("<Q",raw,i)[0]
    off=i
    if v==0:
        print(f"slot {off:#04x}  off {off:#04x}  (null)")
        continue
    name=fmap.get(v,"?")
    print(f"slot {off:#04x}  off {off:#04x}  {v:#x}  {name}")
